"""Starta första MLP-experimentet utan någon ZIP-fil.

Spara denna fil i projektroten SSY226-Group2, eller i dess pythoncode-mapp.
Kör med projektets befintliga .venv:
    python -m pip install CoolProp==8.0.0
    python starta_mlp_experiment.py

Programmet innehåller samma kommenterade Python-kod som träningspaketet.
Det skriver ut koden till pythoncode/mlp_experiment_code, läser dina befintliga
MATLAB-exporter och förbereder och tränar sedan modellen. Ingen ny simulering
behövs. Din SLX-fil och dina ursprungliga MAT-filer ändras inte.

Försöket har åtta uppmätta tillstånd och ett modelluppskattat inredningstillstånd.
Det uppskattade tillståndet används inte som facit. Uppstart före 30 s utesluts.
-7 C förbereds men används inte för modellval eller prediktionsutvärdering.
"""
from pathlib import Path
import argparse
import base64
import hashlib
import importlib.util
import json
import subprocess
import sys
import zlib

# Här finns försökskoden komprimerad, så du bara behöver en enda fil.
# Ingen kod eller data hämtas från internet när detta program körs.
PAYLOAD = ''
EXPECTED_SHA256 = '07981b4b08385ca2eab71debf42c385a4c0a72c9d6e8e6074eaff9f4ed05913d'


def main():
    ap=argparse.ArgumentParser(description='Förbered och träna MLP från befintliga MATLAB-exporter, utan ZIP')
    ap.add_argument('--project-root',type=Path,help='Valfritt: explicit sökväg till SSY226-Group2')
    ap.add_argument('--prepare-only',action='store_true',help='Förbered numeriska data men starta inte nätverksträningen')
    ap.add_argument('--extract-only',action='store_true',help='Skriv bara ut de kommenterade kodfilerna')
    args=ap.parse_args()
    here=Path(__file__).resolve().parent
    root=(args.project_root.resolve() if args.project_root else
          here.parent if here.name.lower()=='pythoncode' else here)
    if not args.extract_only:
        # Vi kontrollerar förutsättningarna innan arbetsfiler skrivs.
        required={'torch':'torch','numpy':'numpy','scipy':'scipy','matplotlib':'matplotlib',
                  'casadi':'casadi','CoolProp':'CoolProp==8.0.0'}
        missing=[package for module,package in required.items() if importlib.util.find_spec(module) is None]
        if missing:
            print('Installera dessa paket i samma .venv och kör igen:')
            print('python -m pip install '+' '.join(missing))
            raise SystemExit(1)
        base=root/'Data'/'NN_training'
        if not (base/'context_raw').is_dir():
            raise SystemExit('Hittar inte Data/NN_training/context_raw. Spara startfilen i projektroten SSY226-Group2.')
        for name in ('vehicle_com.casadi','com_metadata.json'):
            if not (base/'COM'/name).is_file():
                raise SystemExit('Hittar inte '+str(base/'COM'/name)+'. Behåll den tidigare COM-exporten på denna plats.')
        if not any(root.rglob('tunedVariables_minus5_minus10.mat')):
            raise SystemExit('Lägg din befintliga tunedVariables_minus5_minus10.mat i projektroten och kör igen.')
    raw=zlib.decompress(base64.b64decode(PAYLOAD))
    if hashlib.sha256(raw).hexdigest()!=EXPECTED_SHA256:
        raise SystemExit('Startfilens inbäddade kod är skadad. Avbryter.')
    codes=json.loads(raw)
    code_dir=root/'pythoncode'/'mlp_experiment_code'
    code_dir.mkdir(parents=True,exist_ok=True)
    for name,text in codes.items():
        if Path(name).name!=name or not name.endswith('.py'):
            raise SystemExit('Ogiltigt inbäddat filnamn')
        target=code_dir/name
        # Spara egna eventuella ändringar innan en annan kodversion skrivs ut.
        if target.exists() and target.read_text(encoding='utf-8')!=text:
            backup=target.with_suffix('.py.previous')
            counter=1
            while backup.exists():
                backup=target.with_suffix('.py.previous'+str(counter));counter+=1
            target.replace(backup)
        target.write_text(text,encoding='utf-8')
    print('Projekt:',root,flush=True)
    print('Kommenterad kod:',code_dir,flush=True)
    if args.extract_only:return
    steps=['05_granska_traningskontext.py','07_forbered_observerat_mlp_experiment.py']
    if not args.prepare_only:steps.append('08_trana_mlp_experiment.py')
    for name in steps:
        print('\nKör '+name,flush=True)
        subprocess.run([sys.executable,str(code_dir/name)],cwd=root,check=True)
    print('\nKlart. Figurer och modell finns under Data/NN_training/mlp_experiment_results.',flush=True)
    if args.prepare_only:print('Endast data förbereddes; ingen träning startades.',flush=True)


if __name__=='__main__':main()
